import json, numpy as np, itertools
rows=[json.loads(l) for l in open('examples.jsonl')]
for s in range(4):
    r=[x for x in rows if x['skill']==s]
    A=np.array([x['a'] for x in r]);B=np.array([x['b'] for x in r]);Y=np.array([x['answer'] for x in r])
    print('skill',s,'hist',np.bincount(Y,minlength=16).tolist())
    res=[]
    # linear mod m
    for m in [16,17,31,32,63,64]:
        for al in range(m if m<20 else 32):
            for be in range(m if m<20 else 32):
                base=(al*A+be*B)
                for ga in range(m if m<20 else 32):
                    v=(base+ga)%m
                    if m>16: v=v%16
                    res.append((float((v==Y).mean()),'lin',m,al,be,ga))
    res.sort(reverse=True); print(res[:3])
    # quadratic mod 16
    res=[]
    for ab in range(16):
      for aa in range(16):
        for bb in range(16):
            q=ab*A*B+aa*A*A+bb*B*B
            for al in range(16):
                for be in range(0,16):
                    w=(q+al*A+be*B)%16
                    d=(Y-w)%16
                    c=np.bincount(d,minlength=16)
                    res.append((float(c.max()/64),ab,aa,bb,al,be,int(c.argmax())))
    res.sort(reverse=True); print('quad16',res[:3])
    # per output bit: best parity of input bits with const
    X=np.stack([(A>>i)&1 for i in range(5)]+[(B>>i)&1 for i in range(5)],1)
    for k in range(4):
        yb=(Y>>k)&1; best=[]
