            bits=np.array([(mask>>j)&1 for j in range(10)])
            p=(X@bits)%2
            acc=float((p==yb).mean()); best.append((max(acc,1-acc),mask))
        best.sort(reverse=True); print(' bit',k,[(round(a,2),bin(m)) for a,m in best[:2]], 'mean',round(float(yb.mean()),2))

